  chatGreeting:
    "Ich kann Aufgaben anzeigen, anlegen, ändern, löschen und Anfragen senden. Probieren Sie \"zeige überfällige Aufgaben\" oder \"neue Aufgabe Pricing-Deck prüfen, fällig Freitag\".",
  aiAskClaude: "Claude fragen",
  aiAskClaudeOnPage: "Auf dieser Seite",
  aiAskClaudeGeneral: "Allgemein",
  aiPromptExplainLabel: "Das hier erklären",
  aiPromptExplainBody: "Erkläre diese Ansicht: was sie zeigt, was die wichtigsten Begriffe und Indikatoren bedeuten und was ich hier tun kann. Halte es knapp und stütze dich auf den Funktionsleitfaden der aktuellen Ansicht.",
  aiPromptWhatsNextLabel: "Was kommt als Nächstes?",
  aiPromptWhatsNextBody: "Durchsuche das gesamte Projekt und nenne die 3-5 wichtigsten offenen Punkte, die ich jetzt kennen sollte.",
  aiPromptProcessAttachmentLabel: "Anhang verarbeiten",
  aiPromptProcessAttachmentBody: "Extrahiere die wichtigsten Informationen aus dem/den angehängten Dokument(en) - Aufgaben, Risiken, Probleme, Entscheidungen, Meilensteine, Stakeholder, Termine und Budgetzahlen. Fasse zusammen, was du gefunden hast, und nenne mir dann genau, welche Datensätze du anlegen oder aktualisieren würdest (samt Feldern), bevor du etwas tust. Warte auf meine ausdrückliche Bestätigung, bevor du eine Anlege-, Aktualisierungs- oder Löschoperation ausführst.",
  aiPromptRiskReviewLabel: "Risikoüberblick",
  aiPromptRiskReviewBody: "Sieh dir die Projektsituation an. Nenne die größten Risiken, ihre wahrscheinlichen Auswirkungen und die besten nächsten Schritte.",
  aiPromptWeeklyStatusLabel: "Wochenstatus",
  aiPromptWeeklyStatusBody: "Mach aus diesen Projektinformationen einen klaren wöchentlichen Statusbericht mit Fortschritt, Blockern, Risiken und nächsten Schritten.",
  aiPromptStakeholderUpdateLabel: "Stakeholder-Update",
  aiPromptStakeholderUpdateBody: "Entwirf ein Stakeholder-Update für dieses Projekt. Halte es knapp, professionell und auf das fokussiert, was für die Zielgruppe am wichtigsten ist.",
  aiPromptPrioritizeTasksLabel: "Aufgaben priorisieren",
  aiPromptPrioritizeTasksBody: "Hilf mir, alle Aufgaben zu priorisieren. Ordne sie nach Dringlichkeit, Wirkung und Abhängigkeiten und empfiehl dann, was zuerst zu tun ist.",
  aiPromptDashHealthLabel: "Bewertungen erklären",
  aiPromptDashHealthBody: "Erkläre, was jede RAG-Bewertung (Zeitplan, Budget, Scope) treibt und ob eine Bewertung geändert werden sollte.",
  aiPromptDashRisksLabel: "Zeitplan-Risiken",
  aiPromptDashRisksBody: "Was sind aktuell die größten Risiken für die Einhaltung des Zeitplans?",
  aiPromptOpenOverdueLabel: "Überfällig & Blocker",
