  aiPromptOpenFocusLabel: "Fokus für heute",
  aiPromptOpenFocusBody: "Auf welche offenen Punkte sollte ich mich heute angesichts Fälligkeit und Priorität konzentrieren?",
  aiPromptRaidTopLabel: "Größte Risiken",
