  aiPromptTrendActLabel: "Auf Trend reagieren",
  aiPromptTrendActBody: "Was sollte ich angesichts der aktuellen Trends tun, um im Plan zu bleiben?",
  aiPromptOpenStaleLabel: "Liegen geblieben",
  aiPromptOpenStaleBody: "Liste die Aufgaben auf, die nicht erledigt, aber überfällig sind, und markiere „In Bearbeitung“-Aufgaben, die länger nicht aktualisiert wurden, damit ich sie nachfassen oder zurücksetzen kann.",
  aiPromptScUpcomingLabel: "Anstehende Sitzungen",
