  aiPromptRaciGapsBody: "Wer sollte basierend auf Einfluss und Interesse der Stakeholder für die anstehenden Meilensteine jeweils Rechenschaftspflichtig sein?",
  aiPromptRaciOverloadLabel: "Überlastung vermeiden",
  aiPromptRaciOverloadBody: "Welche Stakeholder haben so viel Einfluss, dass ich sie nicht für zu viele Meilensteine gleichzeitig als Rechenschaftspflichtige(n) einsetzen sollte?",
