  aiPromptPhWorstLabel: "Gesundheit dieses Projekts",
  aiPromptPhWorstBody: "Erkläre die aktuelle Gesundheitsbewertung dieses Projekts und was sie treibt, basierend auf dem Dashboard-Snapshot.",
  aiPromptPhCompareLabel: "Kannst du vergleichen?",
  aiPromptPhCompareBody: "Kannst du dieses Projekt von hier aus mit dem Rest des Portfolios vergleichen? Falls nicht, erkläre stattdessen, was du mir über dieses Projekt sagen kannst.",
  aiPromptDraftStatusDocLabel: "Statusbericht entwerfen",
  aiPromptDraftStatusDocBody: "Erstelle ein Projektdokument mit dem Status dieser Woche: Fortschritt, Risiken und nächste Schritte.",
  aiPromptSteeringDeckLabel: "Steering-Deck entwerfen",
  aiPromptSteeringDeckBody: "Erstelle eine Steering-Committee-Präsentation zu Umfang, Terminplan, Budget und den größten Risiken.",
  versionHighlightAiAskClaude: "Claude zu jeder Ansicht fragen: Chat-Starter mit einem Tipp und ansichtsspezifische Vorschläge im KI-Assistenten.",
  versionHighlightUiBatch0990: "Anpassbare Bereiche, Trend-Deltas im Dashboard, gruppierte Berichte und eine klarere Schaltfläche \"Ask Claude\".",
  versionHighlightUiBatch0100: "Abgerundete Tabellenkopfzeilen mit einheitlichem Scrollbalken-Abstand, RAG-Prioritätspunkte, Dialoge schließen per Klick daneben, Wiederherstellung ganzer Versionen samt Nebeneinander-Vergleich und Tooltips im Aufgaben-Editor.",
  versionHighlightUiBatch0101: "Passphrase bestätigen/entfernen und ein zuverlässiges Aufheben für gespeicherte Geheimnisse, zeilenweise Wiederherstellung im Nebeneinander-Vergleich des Verlaufs, Meilensteine & Dokumente in voller Breite mit manuellen Dokument-Links sowie klarere Bedienelemente für Vorlagen und nächste Aktionen.",
  versionHighlightAiWriteTools: "Der KI-Assistent kann jetzt RAID-Einträge, Änderungsanträge, Meilensteine und Stakeholder anlegen, aktualisieren und löschen – nicht mehr nur Aufgaben.",
  aiCreateHeading: "Mit KI erstellen",
