  wizardImportErrorTooLarge: "Diese Datei ist zu groß (max. 20 MB).",
  wizardImportErrorConfluenceUrl: "Diese Confluence-URL konnte nicht gelesen werden.",
  wizardImportErrorSource: "Import aus dieser Quelle nicht möglich.",
  wizardImportErrorEncrypted: "Diese Datei ist kennwortgeschützt. Speichere sie ohne Schutz und versuche es erneut.",
  versionHighlightAiCreateWizard: "Erstellen Sie ein Projekt aus einer Beschreibung in natürlicher Sprache – Claude schlägt Einrichtung und Startinhalte vor.",
  versionHighlightAiActionSuggestions: "Action Center: KI-Triage per Klick + vorgeschlagene nächste Schritte",
  versionHighlightScheduledJobs: "Planen Sie wiederkehrende KI-Portfolioanalysen, die als Benachrichtigungen und als In-App-Verlauf erscheinen.",
  versionHighlightInstallable: "Installieren Sie den Tracker als Desktop- oder Mobil-App für den schnellen Start vom Startbildschirm oder Dock.",
  versionHighlightTaskStatus: "Aufgaben haben jetzt einen Workflow-Status (Zu erledigen bis Erledigt) mit Statusspalte, Inline-Statusbearbeitung und einem Schalter zum Ausblenden erledigter Aufgaben.",
  versionHighlightKanban: "Aufgaben lassen sich jetzt als Drag-and-drop-Kanban-Board nach Status anzeigen; mit Jira synchronisierte Aufgaben bleiben schreibgeschützt auf ihrem Jira-Status, und der Editor erhielt Schaltflächen für Anfrage senden / Zu Jira senden / Löschen.",
  versionHighlightWeightSuggest: "Claude kann jetzt Anpassungen Ihrer Priorisierungsgewichte für nächste Aktionen aus Projekt, Trends und Ihrem Verhalten vorschlagen — prüfen Sie jeden Vorschlag in den Einstellungen und übernehmen Sie die gewünschten.",
  versionHighlightProjectImport: "Erstellen Sie ein Projekt, indem Sie eine Datei, ein SharePoint-Dokument oder eine Confluence-Seite importieren — die KI liest es und füllt den Assistenten für neue Projekte vor.",
  versionHighlightSteering: "Lenkungsausschuss: Erfassen Sie Mitglieder, den Sitzungsplan und Regeln für den Vorlauf von Informationspaketen. Erinnerungen erscheinen im Aktionscenter, und Sitzungen samt Erinnerungen können in Ihren Outlook-Kalender übertragen werden.",
  versionHighlightTour: "Geführte Tour + Demo: ein Rundgang durch die wichtigsten Bereiche beim ersten Start (moderne Ansicht), ein Demo-Projekt zum Erkunden per Klick und ein Eintrag \"Tour starten\" im Hilfe-Menü zum jederzeitigen Wiederholen.",
  versionHighlightTimezones: "Zeitzonen (Grundlage): Legen Sie eine Betriebszeitzone pro Projekt und einen geräteweiten Standard fest; die Datumslogik der App (überfällig, Erinnerungen, Fälligkeiten) richtet sich jetzt nach Ihrer Zeitzone statt nach UTC.",
  versionHighlightTimezoneDisplay: "Zeitzonen-Anzeige: Zeitstempel (Aktivitätsprotokoll, Versionsverlauf, Trends) erscheinen jetzt in einer oben wählbaren Anzeige-Zeitzone — standardmäßig Ihre konfigurierte Zone — mit Zonenangabe. Die Auswahl gilt pro Sitzung.",
  versionHighlightTimezoneCalendar: "Kalender-Zeitzonen: Die Kalenderansicht zeigt eine Live-Leiste mit der aktuellen Zeit in Ihrer Standard-Zeitzone sowie jeder weiteren konfigurierten Zone — praktisch für verteilte Teams.",
  versionHighlightAiFeatureGuide: "Der KI-Assistent versteht die App: Ein integrierter, ansichtsbezogener Funktionsleitfaden lässt ihn erklären, was jeder Bereich kann, und Sie zu Funktionen führen — fragen Sie einfach \"Wie mache ich …?\".",
  versionHighlightJiraEncryption: "Ihr Jira-API-Token wird jetzt verschlüsselt gespeichert (AES-256-GCM, gerätegebunden) statt im Klartext — wie der Anthropic-Schlüssel und das Turso-Token.",
  versionHighlightLandingCockpit:
    "Das Dashboard ist jetzt ein Landing-Cockpit: eine Begrüßung und eine „Seit deinem letzten Besuch“-Leiste zeigen, was sich geändert hat (neue Einträge, Statuswechsel), und die priorisierte Nächste-Schritte-Liste steht oben, damit du zuerst siehst, was dich braucht.",
  versionHighlightMilestoneHorizon:
    "Die Meilensteinliste im Dashboard ist jetzt ein „Was kommt“-Horizont: Überfällig, Diese Woche, Nächste 2 Wochen und Später – so siehst du den Weg nach vorn auf einen Blick.",
  versionHighlightCoaching:
    "Neue Projekte erhalten im Dashboard eine „Erste Schritte“-Karte mit Ein-Klick-Schritten – Aufgabe anlegen, KI-Assistenten einrichten, Meilenstein anlegen, Budget einrichten – die verschwindet, sobald es losgeht.",
  versionHighlightTrendArrows:
    "Die wichtigsten Kennzahlen im Dashboard – Fertigstellung, überfällige Aufgaben, offene RAID – zeigen jetzt einen Trendpfeil und die Veränderung seit deinem letzten Besuch, damit du auf einen Blick siehst, in welche Richtung sich das Projekt bewegt.",
  versionHighlightBurndownSparkline:
    "Das Dashboard zeigt jetzt unter den Kennzahlen eine kleine Trendlinie zum Fertigstellungsgrad, sodass auf einen Blick sichtbar ist, wie sich der Fortschritt über die letzten Snapshots oder Aktivitäten entwickelt hat.",
  versionHighlightDashboardDensity:
    "Das Dashboard hat einen neuen Umschalter für die Dichte (Komfortabel/Kompakt) – wechsle zu Kompakt, um die Abstände zu verringern und mehr vom Cockpit auf dem Bildschirm unterzubringen. Deine Wahl wird pro Gerät gespeichert.",
