  viewHintRaci: "RACI klärt, wer je Meilenstein verantwortlich (R), rechenschaftspflichtig (A), konsultiert (C) und informiert (I) ist – kein Rätselraten mehr.",
  viewHintBudget: "Das Budget plant Aufwand und Kosten je Rolle und Periode. Vergleichen Sie es mit den Ist-Werten, um Mehrausgaben früh zu erkennen.",
  viewHintBudgetReport: "Dieser Bericht vergleicht geplantes und tatsächliches Budget sowie Aufwand, damit Sie sehen, wohin Geld und Stunden fließen.",
  viewHintResources: "Ressourcen sind die Personen, die die Arbeit leisten. Erfassen Sie Rollen, Kapazität und Abwesenheiten für eine realistische Planung.",
