  modeSimple: "Einfach",
  modeModular: "Modular",
  modeAdvanced: "Erweitert",
  modeBadgeLabel: "Aktueller Modus",
  modePresetSimple: "Einfach",
  modePresetAdvanced: "Erweitert",
  modeModulesHeading: "Funktionen",
  modeIntro: "Legen Sie fest, welche Funktionen dieses Projekt verwendet. Jedes Projekt hat seine eigene Auswahl -- beim Wechsel des Projekts werden die jeweiligen Funktionen geladen.",
  modeRetentionNote: "Vorhandene Daten bleiben erhalten und erscheinen wieder, sobald Sie eine Funktion erneut aktivieren.",
  modeSave: "Speichern",
  modeDiscard: "Verwerfen",
  versionHighlightModes: "Einfach- / Modular- / Erweitert-Modus: App auf Aufgaben, Chat und Berichte reduzieren und Funktionen nach Bedarf wieder aktivieren.",
  versionHighlightClarke: "Stakeholder-Kommunikationserinnerungen weisen darauf hin, wichtige Stakeholder vor Meilensteinen, RAID-Einträgen und Änderungen einzubinden.",
  versionHighlightFieldFeedback: "Eingabe-Feedback: Zeichenzähler, Anpassungshinweise und eine Zusammenfassung beim Speichern, wenn Eingaben auf Grenzwerte angepasst wurden.",
  versionHighlightButler: "KI-Assistent (umbenannt von Chat): Vorschlaege, Token-Nutzungsanzeige, Stopp-Schaltflaeche, Pop-out. Konfigurierbarer Dokumentexport. Erinnerungsvorlaufzeiten und Banner-Umschalter. Aktivitaetslog erweitert; Informationsfluss-Diagramm in den Einstellungen.",
  versionHighlightVinge: "Multi-Projekt- / Portfolio-Verwaltung (Phase 1): projektbezogene Arbeitsbereiche mit Projekt-Metadaten-Header, Portfolio-Registrierung und Wechsel, Projektverwaltungsansicht, Erstellen-/Bearbeitungsformular, Leerzustand, projektbezogener Export.",
  versionHighlightTursoMultiProject: "Turso-Multi-Projekt: Eine gemeinsame Datenbank enthält Ihr gesamtes Portfolio – mit projektweisem Wechsel, Archivieren/Wiederherstellen und endgültigem Löschen.",
  versionHighlightSpDocLinks: "SharePoint-Dateien & -Ordner mit Aufgaben, RAID, Änderungen, Stakeholdern, Meilensteinen und Projekten verknüpfen — mit integriertem Browser.",
  versionHighlightFieldVisibility: "Feldsichtbarkeit: Einfache, erweiterte oder vollständige Felder je Editor – mit Zahnrad zum Anpassen der angezeigten Felder",
  versionHighlightTemplates: "Projektvorlagen: die Feldsichtbarkeit und optionalen Startinhalt eines Projekts als wiederverwendbare Vorlage speichern und auf ein Projekt anwenden, um die Feldsichtbarkeit zu setzen und Startinhalt hinzuzufügen",
  versionHighlightPerProjectFunctions: "Projektbezogene Funktionen: jedes Projekt behält seine eigenen aktivierten Module, ohne Neuladen umschaltbar, konfiguriert (mit einer Vorlage) in einem neuen 3-stufigen Erstellungsassistenten",
  versionHighlightTemplateSuggest: "Intelligenter Vorlagenvorschlag: der Erstellungsassistent empfiehlt und wählt anhand von Größe, Komplexität und Team Ihres Projekts die am besten passende Vorlage vor",
  versionHighlightRecovery: "Notfall-Wiederherstellung: ?safe=1-Start und eine /recovery-Seite setzen die Konfiguration zurück, ohne Daten zu verlieren",
  versionHighlightUiPolishBatch: "UI-Politur: klickbare Zeilen, ein farbcodierter RACI-Chip-Picker und Feld-Tooltips in den Editoren",
